+	context: Context,
+	options?: AnthropicVertexOptions,
+) => {
+	const projectId = resolveProject(options);
+	const baseURL = resolveCustomBaseUrl(options?.baseUrl) ?? resolveCustomBaseUrl(model.baseUrl);
+	const vertexClient = new AnthropicVertex({
+		...(projectId ? { projectId } : {}),
+		region: resolveLocation(options),
+		...(baseURL ? { baseURL } : {}),
+		defaultHeaders: buildDefaultHeaders(model, options),
+		...(options?.timeoutMs !== undefined ? { timeout: options.timeoutMs } : {}),
+		maxRetries: options?.maxRetries ?? 0,
