+	// implements with the same SDK streaming abstraction as the direct client.
+	const client = vertexClient as unknown as Anthropic;
+
+	return streamAnthropic(model as unknown as Model<"anthropic-messages">, context, {
+		...options,
+		client,
+		apiKey: undefined,
+	} satisfies AnthropicOptions);
+};
