+	}
+
+	if (model.compat?.forceAdaptiveThinking === true) {
+		return streamAnthropicVertex(model, context, {
+			...base,
+			thinkingEnabled: true,
+			effort: mapThinkingLevelToEffort(model, options.reasoning),
+		} satisfies AnthropicVertexOptions);
+	}
